package com.wolf.osrsdash;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/*
 * Dev launcher. Runs the full RuneLite client with this plugin
 * side-loaded, so you can test it locally without publishing to the
 * Plugin Hub. Run this main() from IntelliJ, or via the shadowJar.
 *
 * This file lives in src/test so it never ships in the plugin jar.
 */
public class OsrsDashPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(OsrsDashPlugin.class);
        RuneLite.main(args);
    }
}

package com.wolf.osrsdash;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/*
 * Buffers DashEvents and flushes them to the backend in batches.
 *
 * Design:
 *  - Events are queued, not sent immediately — StatChanged can fire
 *    rapidly, so we batch and flush on a timer (see the plugin's
 *    scheduled flush).
 *  - On a failed flush, the batch is put BACK on the queue so the
 *    next flush retries it. Cheap insurance against brief network
 *    blips or the Beelink being momentarily down.
 *  - The queue is bounded so a long outage can't grow it forever.
 */
@Slf4j
public class DashSender
{
    private static final MediaType JSON = MediaType.parse("application/json");
    private static final int MAX_QUEUE = 5000;   // drop oldest beyond this
    private static final int MAX_BATCH = 200;    // events per POST

    private final OkHttpClient http;
    private final Gson gson;
    private final ConcurrentLinkedQueue<DashEvent> queue = new ConcurrentLinkedQueue<>();

    private volatile String baseUrl = "";
    private volatile String token = "";

    // Gson is injected from the client — the Plugin Hub forbids creating
    // fresh Gson instances (always reuse the client's shared one).
    public DashSender(OkHttpClient http, Gson gson)
    {
        this.http = http;
        this.gson = gson;
    }

    public void configure(String baseUrl, String token)
    {
        // Trim a trailing slash so we can append "/api/ingest" cleanly.
        this.baseUrl = baseUrl == null ? "" : baseUrl.replaceAll("/+$", "");
        this.token = token == null ? "" : token.trim();
    }

    /** Queue one event for the next flush. */
    public void enqueue(DashEvent event)
    {
        queue.add(event);
        while (queue.size() > MAX_QUEUE)
        {
            queue.poll(); // shed oldest — recent data matters more
        }
    }

    /** Send up to MAX_BATCH queued events. Safe to call on a timer. */
    public void flush()
    {
        if (baseUrl.isEmpty() || token.isEmpty() || queue.isEmpty())
        {
            return;
        }

        // Drain a batch off the queue.
        List<DashEvent> batch = new ArrayList<>();
        for (int i = 0; i < MAX_BATCH; i++)
        {
            DashEvent e = queue.poll();
            if (e == null)
            {
                break;
            }
            batch.add(e);
        }
        if (batch.isEmpty())
        {
            return;
        }

        String body = gson.toJson(batch);
        Request request = new Request.Builder()
            .url(baseUrl + "/api/ingest")
            .header("X-Ingest-Token", token)
            .post(RequestBody.create(JSON, body))
            .build();

        http.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                // Network failure — requeue the batch for next flush.
                log.debug("osrs-dash flush failed, requeueing {} events", batch.size());
                requeue(batch);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful())
                    {
                        // 5xx => transient, retry. 4xx => our bug or a
                        // bad token; don't spin forever, just log it.
                        if (r.code() >= 500)
                        {
                            requeue(batch);
                        }
                        else
                        {
                            log.warn("osrs-dash backend rejected batch: HTTP {}", r.code());
                        }
                    }
                }
            }
        });
    }

    private void requeue(List<DashEvent> batch)
    {
        // Re-add at the tail; ordering is best-effort, not strict.
        for (DashEvent e : batch)
        {
            queue.add(e);
        }
        while (queue.size() > MAX_QUEUE)
        {
            queue.poll();
        }
    }

    public int pending()
    {
        return queue.size();
    }
}

package com.wolf.osrsdash;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/*
 * Settings panel for the plugin. RuneLite renders each @ConfigItem
 * automatically under Settings -> OSRS Dashboard.
 */
@ConfigGroup("osrsdash")
public interface OsrsDashConfig extends Config
{
    @ConfigItem(
        keyName = "backendUrl",
        name = "Backend URL",
        description = "Base URL of the dashboard backend, e.g. https://osrs.gougefam.com",
        position = 1
    )
    default String backendUrl()
    {
        return "http://localhost:4100";
    }

    @ConfigItem(
        keyName = "ingestToken",
        name = "Ingest Token",
        description = "Your personal token from /api/groups/join. Shown once — paste it here.",
        secret = true,
        position = 2
    )
    default String ingestToken()
    {
        return "";
    }

    @ConfigItem(
        keyName = "flushSeconds",
        name = "Flush interval (s)",
        description = "How often buffered events are sent to the backend.",
        position = 3
    )
    default int flushSeconds()
    {
        return 30;
    }

    @ConfigItem(
        keyName = "enabled",
        name = "Send data",
        description = "Master switch — turn off to stop sending entirely.",
        position = 4
    )
    default boolean enabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "minLootValue",
        name = "Min loot value (gp)",
        description = "Only send a loot event when a single item in the drop is worth at least this many coins. "
            + "Keeps noise down — bones and herbs won't trigger dry-streak records. Default 50,000.",
        position = 5
    )
    default int minLootValue()
    {
        return 50_000;
    }
}

package com.wolf.osrsdash;

import java.util.HashMap;
import java.util.Map;

/*
 * One event in the backend's ingest contract:
 *   { type, event_ts, payload }
 * The backend derives `account` from the token, so it is NOT sent.
 *
 * Gson serializes the public fields directly. payload is a free-form
 * map so each event type can carry its own shape.
 */
public class DashEvent
{
    public String type;
    public long event_ts;
    public Map<String, Object> payload;

    private DashEvent(String type)
    {
        this.type = type;
        this.event_ts = System.currentTimeMillis();
        this.payload = new HashMap<>();
    }

    public static DashEvent xp(String skill, long xp)
    {
        DashEvent e = new DashEvent("xp");
        e.payload.put("skill", skill);
        e.payload.put("xp", xp);
        return e;
    }

    public static DashEvent kill(String boss, int kc)
    {
        DashEvent e = new DashEvent("kill");
        e.payload.put("boss", boss);
        if (kc > 0)
        {
            e.payload.put("kc", kc);
        }
        return e;
    }

    public static DashEvent session(String action)
    {
        DashEvent e = new DashEvent("session");
        e.payload.put("action", action); // "start" | "end"
        return e;
    }

    /**
     * A notable loot drop from an NPC. Sent when a single item in the
     * drop clears the configured minimum-value threshold.
     *
     * @param npcName  name of the NPC (e.g. "Vorkath")
     * @param item     display name of the most valuable item
     * @param value    total stack value in coins (0 = unknown)
     * @param qty      quantity of that item
     */
    public static DashEvent loot(String npcName, String item, long value, int qty)
    {
        DashEvent e = new DashEvent("loot");
        e.payload.put("boss", npcName);
        e.payload.put("item", item);
        if (value > 0)
        {
            e.payload.put("value", value);
        }
        if (qty > 1)
        {
            e.payload.put("qty", qty);
        }
        return e;
    }

    /**
     * A quest completion. Sent once when the "Quest Complete!" screen fires.
     *
     * @param questName  name of the completed quest
     */
    public static DashEvent quest(String questName)
    {
        DashEvent e = new DashEvent("quest");
        e.payload.put("quest", questName);
        return e;
    }
}

package com.wolf.osrsdash;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.Collection;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import okhttp3.OkHttpClient;

/*
 * OSRS Dashboard companion plugin.
 *
 * Captures five event types and POSTs them to the dashboard backend:
 *   - xp:      per-skill XP, on StatChanged (deltas + a login snapshot)
 *   - kill:    boss kill counts, parsed from game chat
 *   - loot:    notable drops (≥ minLootValue gp), on NpcLootReceived
 *   - quest:   quest completions, detected by watching Quest state
 *              transition to FINISHED (RuneLite has no completion event)
 *   - session: login / logout boundaries
 *
 * The plugin sends only raw facts. All interpretation (XP/hr, dry
 * streaks, projections, competition gains) happens in the backend.
 */
@Slf4j
@PluginDescriptor(
    name = "OSRS Dashboard",
    description = "Sends XP, boss KC and session data to your dashboard backend",
    tags = {"dashboard", "ironman", "tracker", "xp"}
)
public class OsrsDashPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OsrsDashConfig config;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private ItemManager itemManager;

    @Inject
    private Gson gson;

    private DashSender sender;

    // Last XP seen per skill — lets us skip no-op StatChanged events
    // and avoid sending duplicate snapshots.
    private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);

    // Guards the once-per-login full snapshot.
    private boolean snapshotSent = false;

    // Quest tracking. RuneLite has no quest-completion event, so we watch
    // for a quest's state transitioning to FINISHED. On login we record
    // the already-finished set silently (the baseline) so we only ever
    // send quests completed during this session. A VarbitChanged marks a
    // rescan pending; the next GameTick does the (cheap) scan on the
    // client thread.
    private final Set<Quest> finishedQuests = new HashSet<>();
    private boolean questBaselineDone = false;
    private boolean questCheckPending = false;

    @Override
    protected void startUp()
    {
        sender = new DashSender(okHttpClient, gson);
        applyConfig();
        log.debug("OSRS Dashboard plugin started");
    }

    @Override
    protected void shutDown()
    {
        if (sender != null)
        {
            sender.flush(); // best-effort final flush
        }
        lastXp.clear();
        snapshotSent = false;
        finishedQuests.clear();
        questBaselineDone = false;
        questCheckPending = false;
        log.debug("OSRS Dashboard plugin stopped");
    }

    private void applyConfig()
    {
        sender.configure(config.backendUrl(), config.ingestToken());
    }

    @Provides
    OsrsDashConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(OsrsDashConfig.class);
    }

    // ---- session boundaries + login snapshot --------------------------

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (!config.enabled())
        {
            return;
        }
        GameState state = event.getGameState();

        if (state == GameState.LOGGED_IN)
        {
            if (!snapshotSent)
            {
                // A fresh login: open a session and send a full XP
                // snapshot of every skill. This guarantees the backend
                // has a competition baseline even if you barely play.
                sender.enqueue(DashEvent.session("start"));
                sendFullSnapshot();
                snapshotSent = true;
                // Re-establish the quest baseline for this login. Quest
                // varbits load shortly after LOGGED_IN, so defer the scan
                // to the next GameTick rather than reading them now.
                questBaselineDone = false;
                questCheckPending = true;
            }
        }
        else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
        {
            if (snapshotSent)
            {
                sender.enqueue(DashEvent.session("end"));
                sender.flush(); // push the session end promptly
                snapshotSent = false;
                questBaselineDone = false;
                questCheckPending = false;
            }
        }
    }

    /** Queue an xp event for every skill — the login baseline. */
    private void sendFullSnapshot()
    {
        for (Skill skill : Skill.values())
        {
            // OVERALL is a derived total, not a real skill — skip it.
            // (Guarded by name so it works whether or not the enum
            // includes it in this client version.)
            if ("Overall".equalsIgnoreCase(skill.getName()))
            {
                continue;
            }
            int xp = client.getSkillExperience(skill);
            lastXp.put(skill, xp);
            sender.enqueue(DashEvent.xp(skill.getName(), xp));
        }
    }

    // ---- XP tracking --------------------------------------------------

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (!config.enabled())
        {
            return;
        }
        Skill skill = event.getSkill();
        int xp = event.getXp();

        // StatChanged also fires for temporary boosts/drains where XP
        // is unchanged — only send when total XP actually moved.
        Integer prev = lastXp.get(skill);
        if (prev != null && prev == xp)
        {
            return;
        }
        lastXp.put(skill, xp);
        sender.enqueue(DashEvent.xp(skill.getName(), xp));
    }

    // ---- boss kill counts ---------------------------------------------

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!config.enabled())
        {
            return;
        }
        KillCountParser.Result kc = KillCountParser.parse(event.getMessage());
        if (kc != null)
        {
            // The chat KC is authoritative — send it as-is so the
            // backend stores the true count, not an inferred one.
            sender.enqueue(DashEvent.kill(kc.boss, kc.kc));
        }
    }

    // ---- loot drops ---------------------------------------------------

    // Fires when an NPC's loot appears on the ground after a kill.
    // We scan the items, find the most valuable one, and record a loot
    // event if it clears the user-configured threshold. This avoids
    // spamming the backend with bones and herbs while still capturing
    // notable drops for dry-streak tracking.
    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        if (!config.enabled())
        {
            return;
        }

        String npcName = event.getNpc().getName();
        if (npcName == null || npcName.isEmpty())
        {
            return;
        }

        Collection<ItemStack> items = event.getItems();
        String bestItem = null;
        long bestValue = 0;
        int bestQty = 1;

        for (ItemStack stack : items)
        {
            int id = stack.getId();
            int qty = stack.getQuantity();

            // Unnote noted items — getItemPrice() needs the base item ID.
            ItemComposition comp = itemManager.getItemComposition(id);
            if (comp.getNote() != -1)
            {
                // getNote() != -1 means this is the noted form; the linked
                // item is the tradeable base item.
                id = comp.getLinkedNoteId();
                comp = itemManager.getItemComposition(id);
            }

            long unitPrice = itemManager.getItemPrice(id);
            long stackValue = unitPrice * qty;

            if (stackValue > bestValue)
            {
                bestValue = stackValue;
                bestItem = comp.getName();
                bestQty = qty;
            }
        }

        // Only send if the best item clears the configured threshold.
        if (bestItem != null && bestValue >= config.minLootValue())
        {
            sender.enqueue(DashEvent.loot(npcName, bestItem, bestValue, bestQty));
            log.debug("osrs-dash loot: {} dropped {} x{} ({}gp) from {}",
                client.getLocalPlayer().getName(), bestItem, bestQty, bestValue, npcName);
        }
    }

    // ---- quest completions --------------------------------------------

    // RuneLite exposes no quest-completion event, so we detect it by
    // watching quest state. A VarbitChanged fires whenever a varbit/varp
    // moves (quest progress is stored in these), so we use it only as a
    // cheap "something changed, rescan soon" signal — the actual scan
    // happens on the next GameTick, both on the client thread.
    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (config.enabled())
        {
            questCheckPending = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.enabled() || !questCheckPending)
        {
            return;
        }
        questCheckPending = false;
        checkQuests();
    }

    // Scan every quest's state. On the first scan after login we just
    // record which quests are already FINISHED (the baseline) and send
    // nothing — that avoids replaying a player's whole quest log on every
    // login. After the baseline, any quest newly FINISHED is a real
    // in-session completion and gets sent.
    private void checkQuests()
    {
        if (!questBaselineDone)
        {
            for (Quest quest : Quest.values())
            {
                if (quest.getState(client) == QuestState.FINISHED)
                {
                    finishedQuests.add(quest);
                }
            }
            questBaselineDone = true;
            return;
        }

        for (Quest quest : Quest.values())
        {
            if (quest.getState(client) == QuestState.FINISHED && finishedQuests.add(quest))
            {
                // add() returned true → this quest wasn't finished before.
                sender.enqueue(DashEvent.quest(quest.getName()));
                log.debug("osrs-dash quest completed: {}", quest.getName());
            }
        }
    }

    // ---- scheduled flush ----------------------------------------------

    // RuneLite calls @Schedule methods on a timer. We flush every 10s;
    // the configured flushSeconds is advisory for future tuning.
    @Schedule(period = 10, unit = java.time.temporal.ChronoUnit.SECONDS)
    public void scheduledFlush()
    {
        if (sender != null && config.enabled())
        {
            applyConfig(); // pick up any settings-panel changes
            sender.flush();
        }
    }
}

package com.wolf.osrsdash;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/*
 * Parses boss kill counts from game chat.
 *
 * Why chat parsing instead of ActorDeath? ActorDeath fires for ANY
 * actor death near you, and several major bosses (Zulrah, Vorkath,
 * raids) don't fire it cleanly for the boss itself. The reliable
 * signal every kill-count plugin uses is the game message the server
 * prints after a kill, e.g.:
 *
 *   "Your Vorkath kill count is: 1,234."
 *   "Your Zulrah kill count is: 57."
 *   "Your King Black Dragon kill count is: 8."
 *
 * Raids and a few bosses use slightly different wording (handled by
 * the second pattern). Anything unmatched is simply ignored.
 */
public final class KillCountParser
{
    // "Your <boss> kill count is: <number>."
    private static final Pattern KC = Pattern.compile(
        "Your (?<boss>.+?) (?:kill|completion) count is: (?<kc>[\\d,]+)"
    );

    // Raids: "Your completed Chambers of Xeric count is: 12."
    private static final Pattern RAID_KC = Pattern.compile(
        "Your completed (?<boss>.+?) count is: (?<kc>[\\d,]+)"
    );

    private KillCountParser()
    {
    }

    /** Result of a successful parse: which boss, and the new KC. */
    public static final class Result
    {
        public final String boss;
        public final int kc;

        Result(String boss, int kc)
        {
            this.boss = boss;
            this.kc = kc;
        }
    }

    /**
     * Try to extract a boss kill count from a chat line.
     * Returns null if the line is not a kill-count message.
     */
    public static Result parse(String message)
    {
        if (message == null || message.isEmpty())
        {
            return null;
        }

        Matcher m = RAID_KC.matcher(message);
        if (m.find())
        {
            return build(m.group("boss"), m.group("kc"));
        }

        m = KC.matcher(message);
        if (m.find())
        {
            return build(m.group("boss"), m.group("kc"));
        }

        return null;
    }

    private static Result build(String boss, String kcRaw)
    {
        try
        {
            int kc = Integer.parseInt(kcRaw.replace(",", ""));
            return new Result(boss.trim(), kc);
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }
}
